head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/COLUMNS/data/COLUMNS.json";   // data(type:bar, columns) 조회

scwin.CHART_CONFIG = {
    global: {
        color:   { theme: "a11y" },                       // 색 테마
        padding: { top: 20, right: 30, bottom: 40, left: 60 },
        animation: { show: true, delay: 100, ease: "easeCubic" },
        onclick: function (data) {                         // 막대 클릭 이벤트
            scwin.click("클릭: " + data.name + " = " + data.value + " (idx " + data.index + ")");
        }
    },
    title: { text: "연도별 분기 실적", position: "top" },   // 제목
    axis: {
        y: {
            min: 0, max: 400,
            label: { text: "금액(만원)" },                 // Y축 라벨
            tick:  { format: function (v) { return v.toLocaleString(); } }  // Y눈금 포맷
        },
        x: { label: { text: "분기" } }                     // X축 라벨
    },
    grid: { y: { show: true } },                           // 가로 격자선
    legend: { show: true, position: "bottom" },            // 범례 하단
    tooltip: {                                             // 커스텀 툴팁
        custom: function (arr) {
            const d = arr[0];
            return '<div style="padding:8px;background:#222;color:#fff;border-left:4px solid #40bcd3;border-radius:4px;">'
                 + '<b>' + d.name + '</b><br/>' + Number(d.value).toLocaleString() + ' 만원</div>';
        }
    },
    extend: {
        bar: { width: 18, borderRadius: 4, topRadius: 4 }  // 막대 폭·모서리
    }
};

scwin.onpageload = async function () {
    const res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    const data = res.responseJSON;
    $c.ext.drawChartData("bar", data, chartWrap, scwin.CHART_CONFIG);
};
scwin.click = function (msg) { 
	$c.win.alert(msg)
};
